-- APPLIED RECEIPT: production transaction 1773, 12 November 2026. DO NOT RERUN.
-- Eight organiser-supplied Wednesday 11 November 2026 results, explicitly approved.
-- Guarded SQL exception to the unavailable admin workflow rehearsed on disposable PostgreSQL.
-- No fixture, team, preference, permission or existing-result changes.
BEGIN;
SET LOCAL lock_timeout='5s';SET LOCAL statement_timeout='30s';
LOCK TABLE public.fixtures,public.result_versions,public.teams,public.competition_seasons IN SHARE ROW EXCLUSIVE MODE;
CREATE TEMP TABLE nov11_fixtures_before ON COMMIT DROP AS SELECT * FROM public.fixtures;
CREATE TEMP TABLE nov11_results_before ON COMMIT DROP AS SELECT * FROM public.result_versions;
CREATE TEMP TABLE nov11_teams_before ON COMMIT DROP AS SELECT * FROM public.teams;
CREATE TEMP TABLE nov11_audit_before ON COMMIT DROP AS SELECT * FROM public.admin_audit_log;
CREATE TEMP TABLE nov11_plan ON COMMIT DROP AS SELECT * FROM jsonb_to_recordset('[{"id": "337f72ec-33c3-4ca6-a7c6-ae00eb9d4428", "home_team_id": "a4eb0d33-ec37-42c2-bb83-b25ac1f046b5", "away_team_id": "a7306808-977f-496c-8f6c-3141529ca76c", "kickoff_time": "19:00:00", "court": 2, "schedule_version": 6, "updated_at": "2026-11-11T12:56:55.882294+00:00", "home": "MTS FC", "away": "Wildcats", "home_score": 5, "away_score": 7}, {"id": "3cfa4307-77e8-4b1f-875f-4e4e138239fe", "home_team_id": "c9f73f23-1e6c-42df-a7fa-9a7953d9cb75", "away_team_id": "bf6a7c6e-83e0-4d6d-8354-9a89ab679eb3", "kickoff_time": "19:00:00", "court": 1, "schedule_version": 4, "updated_at": "2026-11-11T12:56:55.882294+00:00", "home": "Buckle City", "away": "Dream Team", "home_score": 7, "away_score": 5}, {"id": "9d70da5d-6156-4882-8b2a-f212ee727ad6", "home_team_id": "99d1aedc-409b-4495-b32c-c874ec5958e0", "away_team_id": "b7102a75-a3ad-488c-b16e-f6da36e7f7ba", "kickoff_time": "19:40:00", "court": 1, "schedule_version": 4, "updated_at": "2026-10-31T08:45:07.945244+00:00", "home": "King ADL", "away": "AFG", "home_score": 4, "away_score": 3}, {"id": "ff4f4394-c365-491c-b476-5758ac3753fe", "home_team_id": "8f0b3cd6-a819-411e-b08c-b57a3c9367fe", "away_team_id": "2c8b11cb-0809-475a-a9e8-d39834c41ccb", "kickoff_time": "19:40:00", "court": 2, "schedule_version": 6, "updated_at": "2026-10-31T08:45:07.945244+00:00", "home": "Rinnai", "away": "Ibiza", "home_score": 5, "away_score": 8}, {"id": "6b8a7d12-70ce-4af4-b959-3c6e18192887", "home_team_id": "b4b3cb39-f59c-4ea3-b176-8e637bfb7e8b", "away_team_id": "435af587-f6ea-5030-a097-94ad466481c2", "kickoff_time": "20:20:00", "court": 1, "schedule_version": 6, "updated_at": "2026-10-31T08:45:07.945244+00:00", "home": "Ghazni United", "away": "Xaywan", "home_score": 7, "away_score": 1}, {"id": "af9109c0-a053-477a-af98-716462464570", "home_team_id": "8902231b-a7f3-474b-96da-c8b3ac09c74b", "away_team_id": "5b5d3141-f8b7-481e-9e97-9407d8f224b9", "kickoff_time": "20:20:00", "court": 2, "schedule_version": 4, "updated_at": "2026-10-31T08:45:07.945244+00:00", "home": "Pops", "away": "Kuq E Zi", "home_score": 6, "away_score": 7}, {"id": "1db0e8bc-e51f-4a1a-906c-f76be786383e", "home_team_id": "bafe147f-c3ac-4285-8159-f8e13a06e067", "away_team_id": "3a2cbf2d-326d-4a3b-bd94-56ac4f46a999", "kickoff_time": "21:00:00", "court": 2, "schedule_version": 6, "updated_at": "2026-11-11T06:08:12.124252+00:00", "home": "Umoja Stars", "away": "Kawsar FC", "home_score": 3, "away_score": 8}, {"id": "56c55c48-876b-412d-83f1-51ac0e22af69", "home_team_id": "b3be09fa-1f9e-4501-be80-ae0346804d31", "away_team_id": "92b8f805-41b1-446a-b843-6f7cc7083e90", "kickoff_time": "21:00:00", "court": 1, "schedule_version": 10, "updated_at": "2026-11-11T06:08:12.124252+00:00", "home": "Goldlink Up", "away": "Misfits", "home_score": 7, "away_score": 7}]'::jsonb) AS x(id uuid,home_team_id uuid,away_team_id uuid,kickoff_time time,court integer,schedule_version bigint,updated_at timestamptz,home text,away text,home_score integer,away_score integer);
DO $$BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.competition_seasons WHERE id='be008d39-f175-45c1-a232-2148d84b1cf9' AND lifecycle='active' AND publication_state='published') THEN RAISE EXCEPTION 'Edition is not active';END IF;
 IF (SELECT count(*) FROM public.fixtures WHERE competition_season_id='be008d39-f175-45c1-a232-2148d84b1cf9' AND match_date='2026-11-11' AND publication_state='published' AND schedule_status='scheduled')<>8 THEN RAISE EXCEPTION 'Unexpected round size';END IF;
 IF EXISTS(SELECT 1 FROM nov11_plan p LEFT JOIN public.fixtures f USING(id) LEFT JOIN public.teams h ON h.id=f.home_team_id LEFT JOIN public.teams a ON a.id=f.away_team_id WHERE f.id IS NULL OR f.competition_season_id<>'be008d39-f175-45c1-a232-2148d84b1cf9' OR f.round_number<>3 OR f.match_date<>'2026-11-11' OR f.stage<>'regular_season' OR f.publication_state<>'published' OR f.schedule_status<>'scheduled' OR row(f.home_team_id,f.away_team_id,f.kickoff_time,f.court,f.schedule_version,f.updated_at,h.name,a.name) IS DISTINCT FROM row(p.home_team_id,p.away_team_id,p.kickoff_time,p.court,p.schedule_version,p.updated_at,p.home,p.away)) THEN RAISE EXCEPTION 'Fixture baseline changed';END IF;
 IF EXISTS(SELECT 1 FROM public.result_versions WHERE fixture_id IN(SELECT id FROM nov11_plan)) THEN RAISE EXCEPTION 'Result work already exists; inspect before retrying';END IF;
END $$;
INSERT INTO public.result_versions(fixture_id,revision,status,home_score,away_score)
SELECT id,1,'published',home_score,away_score FROM nov11_plan;
DO $$BEGIN
 IF EXISTS(SELECT 1 FROM nov11_fixtures_before b FULL JOIN public.fixtures f USING(id) WHERE to_jsonb(b) IS DISTINCT FROM to_jsonb(f)) THEN RAISE EXCEPTION 'Fixtures changed';END IF;
 IF EXISTS(SELECT 1 FROM nov11_teams_before b FULL JOIN public.teams t USING(id) WHERE to_jsonb(b) IS DISTINCT FROM to_jsonb(t)) THEN RAISE EXCEPTION 'Team profiles changed';END IF;
 IF EXISTS(SELECT 1 FROM nov11_results_before b LEFT JOIN public.result_versions r USING(id) WHERE to_jsonb(b) IS DISTINCT FROM to_jsonb(r)) THEN RAISE EXCEPTION 'Existing results changed';END IF;
 IF (SELECT count(*) FROM public.result_versions)<>(SELECT count(*)+8 FROM nov11_results_before) OR (SELECT count(*) FROM nov11_plan p JOIN public.result_versions r ON r.fixture_id=p.id WHERE r.status='published' AND r.revision=1 AND r.home_score=p.home_score AND r.away_score=p.away_score AND r.forfeit_side IS NULL AND r.published_at IS NOT NULL)<>8 THEN RAISE EXCEPTION 'Result verification failed';END IF;
 IF EXISTS(SELECT 1 FROM nov11_audit_before b LEFT JOIN public.admin_audit_log a USING(id) WHERE to_jsonb(b) IS DISTINCT FROM to_jsonb(a)) THEN RAISE EXCEPTION 'Existing audit changed';END IF;
END $$;
SELECT txid_current() AS transaction_id,p.home,p.home_score,p.away_score,p.away FROM nov11_plan p ORDER BY p.kickoff_time,p.court;
COMMIT;
